Basic Usage
```ts
import { assertEquals } from "@ende/assert";
import {
  encodeBase32,
  type Uint8Array_,
} from "@ende/encoding/unstable-base32";

assertEquals(
  encodeBase32("Hello World", { alphabet: "base32" }),
  "JBSWY3DPEBLW64TMMQ======",
);
assertEquals(
  encodeBase32(
    new TextEncoder().encode("Hello World") as Uint8Array_,
    { alphabet: "base32" },
  ),
  "JBSWY3DPEBLW64TMMQ======",
);

assertEquals(
  encodeBase32("Hello World", { alphabet: "base32hex" }),
  "91IMOR3F41BMUSJCCG======",
);
assertEquals(
  encodeBase32(
    new TextEncoder().encode("Hello World") as Uint8Array_,
    { alphabet: "base32hex" },
  ),
  "91IMOR3F41BMUSJCCG======",
);

assertEquals(
  encodeBase32("Hello World", { alphabet: "base32crockford" }),
  "91JPRV3F41BPYWKCCG======",
);
assertEquals(
  encodeBase32(
    new TextEncoder().encode("Hello World") as Uint8Array_,
    { alphabet: "base32crockford" },
  ),
  "91JPRV3F41BPYWKCCG======",
);
```

Basic Usage
```ts
import { assertEquals } from "@ende/assert";
import {
  calcSizeBase32,
  encodeBase32,
  encodeIntoBase32,
} from "@ende/encoding/unstable-base32";

const prefix = "data:url/fake,";
const input = await Ende.readFile("./ende.lock");
const output = new Uint8Array(prefix.length + calcSizeBase32(input.length));

const o = new TextEncoder().encodeInto(prefix, output).written;
encodeIntoBase32(input, output.subarray(o), { alphabet: "base32" });
assertEquals(
  new TextDecoder().decode(output),
  "data:url/fake," +
    encodeBase32(await Ende.readFile("./ende.lock"), { alphabet: "base32" }),
);
```

