assertEquals(
  decodeBase64("SGVsbG8gV29ybGQ=", { alphabet: "base64" }),
  new TextEncoder().encode("Hello World"),
);

assertEquals(
  decodeBase64("SGVsbG8gV29ybGQ", { alphabet: "base64url" }),
  new TextEncoder().encode("Hello World"),
);
```

